-- TOP4HoneyChains reference data after db/migrations up to 036_d98_seal_emptying.sql, for a new, empty database (D-98, db/install).
-- Generated by tools/DemoSchema (install mode) from the database TOP4HoneyChainsDb_install; lookup and configuration tables only. Do not edit by hand.
-- Each row is inserted only when its key is missing, so the script can run again. Run it after 01_schema.sql:
--   sqlcmd -S <server> -d <new database> -E -I -f 65001 -b -i db\install\02_reference_data.sql   (docs/KURULUM-TR.md, part B)
-- Tables:
--   __EFMigrationsHistory: the Identity tables are already at their EF migration
--   AspNetRoles where NormalizedName IN (N'ADMINISTRATOR', N'BEEKEEPER'): the global roles the code uses (D-60: the others are retired)
--   AssignmentStatuses
--   HoneyTypes
--   BeekeeperEducationLevels
--   BeekeepingPurposeTypes
--   BeekeepingTypes
--   Capabilities
--   OrgRoles
--   CriticalControlPoints
--   CriticalControlPointParameterCategories
--   CriticalControlPointParameters
--   CriticalControlPointParameterLimits
--   CcpResponsibilities (UpdatedByUserId not copied)
--   CcpResponsibilityCapabilities
--   CcpResponsibilityRoles
--   Provinces
--   Districts
--   RolePermissions (UpdatedByUserId not copied)
--   ReferenceTranslations (UpdatedByUserId not copied)
--   Notices where OrgId IS NULL AND IsDraft = 1 AND PublishedByUserId IS NULL (PublishedByUserId not copied): the platform's draft notices seeded by 020 and 029; published versions belong to the instance's data-protection office
--   ReferenceTranslations: only translations of the rows above (not of production periods or parameter contents)
-- Not exported: RawHoneyProductionPeriods (each installation creates its seasons) and CriticalControlPointParameterContents (uploaded videos).

SET NOCOUNT ON;
DECLARE @users int = 0;
IF OBJECT_ID(N'dbo.AspNetUsers', N'U') IS NOT NULL
    EXEC sys.sp_executesql N'SELECT @n = COUNT(*) FROM dbo.AspNetUsers', N'@n int OUTPUT', @n = @users OUTPUT;
IF DB_NAME() IN (N'master', N'model', N'msdb', N'tempdb')
BEGIN
    RAISERROR(N'db/install: run this script in the new, empty TOP4HoneyChains database (sqlcmd -d <database>), not in %s.', 16, 1, N'a system database');
    SET NOEXEC ON;
END;
ELSE IF @users > 0
BEGIN
    RAISERROR(N'db/install: this database already has user accounts. db/install is only for a new, empty database; an existing database is updated with db/migrations.', 16, 1);
    SET NOEXEC ON;
END;
GO
