(N'HoneyType', N'1', N'Description', N'es', N'Miel producida a partir de las secreciones de mielada de los pinos, caracterizada por su color oscuro, aroma intenso y alto contenido mineral.', '2026-10-04T22:37:48.0000000', NULL),
(N'HoneyType', N'1', N'Description', N'lv', N'Medus, kas iegūts no lapu medus izdalījumiem uz priedēm; tam raksturīga tumša krāsa, spēcīgs aromāts un augsts minerālvielu saturs.', '2026-10-04T22:37:48.0000000', NULL),
(N'HoneyType', N'1', N'Description', N'pl', N'Miód wytwarzany ze spadzi na sosnach, o ciemnej barwie, intensywnym aromacie i wysokiej zawartości składników mineralnych.', '2026-10-04T22:37:48.0000000', NULL),
(N'HoneyType', N'1', N'Description', N'tr', N'Çam ağaçlarındaki salgılardan (basra) üretilen; koyu rengi, güçlü aroması ve yüksek mineral içeriğiyle bilinen bal.', '2026-10-04T22:37:48.0000000', NULL),
