(N'HoneyType', N'3', N'Title', N'tr', N'Kekik Balı', '2026-10-04T22:37:14.0000000', NULL),
(N'HoneyType', N'4', N'Description', N'es', N'Miel producida principalmente a partir de néctar de girasol, por lo general de color claro, sabor suave y tendencia moderada a la cristalización.', '2026-10-04T22:37:14.0000000', NULL),
(N'HoneyType', N'4', N'Description', N'lv', N'Medus, kas iegūts galvenokārt no saulespuķu nektāra, parasti gaišā krāsā, ar maigu garšu un mērenu tieksmi kristalizēties.', '2026-10-04T22:37:14.0000000', NULL),
(N'HoneyType', N'4', N'Description', N'pl', N'Miód wytwarzany głównie z nektaru słonecznika, zwykle o jasnej barwie, łagodnym smaku i umiarkowanej skłonności do krystalizacji.', '2026-10-04T22:37:14.0000000', NULL),
(N'HoneyType', N'4', N'Description', N'tr', N'Çoğunlukla ayçiçeği nektarından üretilen; genellikle açık renkli, hafif tatlı ve orta düzeyde kristalleşme eğilimli bal.', '2026-10-04T22:37:14.0000000', NULL),
