(N'HoneyType', N'4', N'Title', N'tr', N'Ayçiçeği Balı', '2026-10-04T22:37:14.0000000', NULL),
(N'HoneyType', N'5', N'Description', N'es', N'Miel obtenida de flores de cítricos, caracterizada por su color claro, su aroma fresco y una capacidad antioxidante relativamente baja.', '2026-10-04T22:37:14.0000000', NULL),
(N'HoneyType', N'5', N'Description', N'lv', N'Medus, kas iegūts no citrusaugu ziediem, raksturīgs ar gaišu krāsu, svaigu aromātu un salīdzinoši zemu antioksidantu kapacitāti.', '2026-10-04T22:37:14.0000000', NULL),
(N'HoneyType', N'5', N'Description', N'pl', N'Miód pozyskiwany z kwiatów cytrusów, charakteryzujący się jasną barwą, świeżym aromatem i stosunkowo niską zdolnością przeciwutleniającą.', '2026-10-04T22:37:14.0000000', NULL),
(N'HoneyType', N'5', N'Description', N'tr', N'Narenciye çiçeklerinden elde edilen; açık rengi, taze aroması ve görece düşük antioksidan kapasitesiyle öne çıkan bal.', '2026-10-04T22:37:14.0000000', NULL),
(N'HoneyType', N'5', N'Title', N'es', N'Miel de cítricos', '2026-10-04T22:37:14.0000000', NULL),
