(N'Parameter', N'1', N'Name', N'es', N'¿Se almacenan las herramientas y los equipos apícolas no utilizados después de una limpieza a fondo?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'1', N'Name', N'lv', N'Vai neizmantotie biškopības darbarīki un aprīkojums tiek uzglabāti pēc rūpīgas tīrīšanas?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'1', N'Name', N'pl', N'Czy nieużywane narzędzia i sprzęt pszczelarski są przechowywane po dokładnym oczyszczeniu?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'1', N'Name', N'tr', N'Kullanılmayan arıcılık alet ve ekipmanları iyice temizlendikten sonra mı depolanıyor?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'10', N'Name', N'es', N'¿Se realizan evaluaciones de riesgos exhaustivas sobre el uso de plaguicidas?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'10', N'Name', N'lv', N'Vai tiek veikti visaptveroši riska novērtējumi attiecībā uz pesticīdu lietošanu?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'10', N'Name', N'pl', N'Czy przeprowadza się kompleksowe oceny ryzyka dotyczące stosowania pestycydów?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'10', N'Name', N'tr', N'Pestisit kullanımına ilişkin kapsamlı risk değerlendirmeleri yapılıyor mu?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'11', N'Name', N'es', N'¿Se presta especial atención al momento, la dosis y la frecuencia de aplicación de los plaguicidas legalmente permitidos, en particular para el control de la varroa?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'11', N'Name', N'lv', N'Vai tiek pievērsta rūpīga uzmanība likumīgi atļauto pesticīdu lietošanas laikam, devai un biežumam, īpaši varrozes kontrolei?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'11', N'Name', N'pl', N'Czy zwraca się szczególną uwagę na termin, dawkowanie i częstotliwość stosowania dopuszczonych prawem pestycydów, zwłaszcza w zwalczaniu warrozy?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'11', N'Name', N'tr', N'Yasal olarak izin verilen pestisitlerin, özellikle varroa mücadelesinde, uygulama zamanına, dozuna ve sıklığına dikkat ediliyor mu?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'12', N'Name', N'es', N'¿Se utilizan métodos de control no químicos para el manejo de plagas siempre que sea posible?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'12', N'Name', N'lv', N'Vai kaitēkļu apkarošanai, kad vien iespējams, tiek izmantotas neķīmiskas kontroles metodes?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'12', N'Name', N'pl', N'Czy w miarę możliwości stosuje się niechemiczne metody zwalczania szkodników?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'12', N'Name', N'tr', N'Zararlı yönetiminde mümkün olduğunca kimyasal olmayan mücadele yöntemleri kullanılıyor mu?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'13', N'Name', N'es', N'¿En qué medida se verifica mediante análisis de laboratorios acreditados la idoneidad del agua utilizada en la producción de miel en cuanto a sus propiedades microbiológicas, químicas y físicas, y con qué frecuencia se realizan estos análisis?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'13', N'Name', N'lv', N'Cik lielā mērā medus ražošanā izmantotā ūdens piemērotība attiecībā uz tā mikrobioloģiskajām, ķīmiskajām un fizikālajām īpašībām tiek pārbaudīta akreditētās laboratorijas testos, un cik bieži šie testi tiek veikti?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'13', N'Name', N'pl', N'W jakim zakresie przydatność wody używanej w produkcji miodu pod względem właściwości mikrobiologicznych, chemicznych i fizycznych jest weryfikowana badaniami w akredytowanym laboratorium i jak często przeprowadza się te badania?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'13', N'Name', N'tr', N'Bal üretiminde kullanılan suyun mikrobiyolojik, kimyasal ve fiziksel özellikler bakımından uygunluğu akredite laboratuvar testleriyle ne ölçüde doğrulanıyor ve bu testler ne sıklıkla yapılıyor?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'14', N'Name', N'es', N'¿Se evalúa y se confirma la idoneidad del agua utilizada para limpiar los equipos?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'14', N'Name', N'lv', N'Vai aprīkojuma tīrīšanai izmantotais ūdens tiek novērtēts un apstiprināts kā piemērots?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'14', N'Name', N'pl', N'Czy woda używana do czyszczenia sprzętu jest oceniana i potwierdzana jako odpowiednia?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'14', N'Name', N'tr', N'Ekipman temizliğinde kullanılan suyun uygunluğu değerlendirilip teyit ediliyor mu?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'15', N'Name', N'es', N'¿Es adecuada la calidad del agua utilizada como materia prima para preparar las soluciones de agua azucarada para la alimentación de las abejas?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'15', N'Name', N'lv', N'Vai bišu barošanai paredzēto cukura šķīdumu pagatavošanā kā izejviela izmantotā ūdens kvalitāte ir atbilstoša?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'15', N'Name', N'pl', N'Czy jakość wody używanej jako surowiec do przygotowania syropu cukrowego do karmienia pszczół jest odpowiednia?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'15', N'Name', N'tr', N'Arı beslemesi için şekerli su çözeltilerinin hazırlanmasında hammadde olarak kullanılan suyun kalitesi uygun mu?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'16', N'Name', N'es', N'¿Se optimiza el momento de la cosecha de miel en función de los indicadores de madurez de la miel y de las fuentes de néctar floral?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'16', N'Name', N'lv', N'Vai medus ievākšanas laiks tiek optimizēts, pamatojoties uz medus gatavības rādītājiem un ziedu nektāra avotiem?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'16', N'Name', N'pl', N'Czy termin miodobrania jest optymalizowany na podstawie wskaźników dojrzałości miodu i źródeł nektaru?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'16', N'Name', N'tr', N'Bal hasadının zamanlaması, balın olgunluk göstergelerine ve çiçek nektarı kaynaklarına göre en uygun şekilde belirleniyor mu?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'17', N'Name', N'es', N'¿Se monitorean las fuentes de peligros físicos (fragmentos metálicos o no metálicos; madera, piedra, vidrio, etc.) que afectan a la calidad de la miel?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'17', N'Name', N'lv', N'Vai tiek uzraudzīti fizikālo apdraudējumu avoti (metāla vai nemetāla daļiņas; koks, akmens, stikls u. c.), kas ietekmē medus kvalitāti?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'17', N'Name', N'pl', N'Czy monitoruje się źródła zagrożeń fizycznych (fragmenty metalowe lub niemetalowe; drewno, kamień, szkło itp.) wpływających na jakość miodu?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'17', N'Name', N'tr', N'Bal kalitesini etkileyen fiziksel tehlike kaynakları (metal parçalar veya metal olmayan; tahta, taş, cam vb.) izleniyor mu?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'18', N'Name', N'es', N'¿Se monitorean las fuentes de peligros biológicos (agentes de contaminación bacteriana, por levaduras y mohos procedentes de factores ambientales) que afectan a la calidad de la miel?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'18', N'Name', N'lv', N'Vai tiek uzraudzīti bioloģisko apdraudējumu avoti (baktēriju, raugu un pelējuma piesārņojuma izraisītāji no vides faktoriem), kas ietekmē medus kvalitāti?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'18', N'Name', N'pl', N'Czy monitoruje się źródła zagrożeń biologicznych (czynniki skażenia bakteriami, drożdżami i pleśniami pochodzące ze środowiska) wpływających na jakość miodu?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'18', N'Name', N'tr', N'Bal kalitesini etkileyen biyolojik tehlike kaynakları (çevresel faktörlerden gelen bakteri, maya ve küf bulaşma etkenleri) izleniyor mu?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'19', N'Name', N'en', N'Are potential sources of chemical hazards (heavy metals, cleaning chemicals, chemicals from cleaning water, medicines and antibiotics, bee repellents or other contaminants of environmental origin) that affect honey quality tracked?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'19', N'Name', N'es', N'¿Se realiza un seguimiento de las posibles fuentes de peligros químicos (metales pesados, productos químicos de limpieza, sustancias químicas del agua de limpieza, medicamentos y antibióticos, repelentes de abejas u otros contaminantes de origen ambiental) que afectan a la calidad de la miel?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'19', N'Name', N'lv', N'Vai tiek izsekoti iespējamie ķīmisko apdraudējumu avoti (smagie metāli, tīrīšanas ķimikālijas, ķimikālijas no tīrīšanas ūdens, zāles un antibiotikas, bišu atbaidīšanas līdzekļi vai citi vides izcelsmes piesārņotāji), kas ietekmē medus kvalitāti?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'19', N'Name', N'pl', N'Czy śledzi się potencjalne źródła zagrożeń chemicznych (metale ciężkie, chemiczne środki czyszczące, chemikalia z wody do mycia, leki i antybiotyki, repelenty dla pszczół lub inne zanieczyszczenia pochodzenia środowiskowego) wpływających na jakość miodu?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'19', N'Name', N'tr', N'Bal kalitesini etkileyen olası kimyasal tehlike kaynakları (ağır metaller, temizlik kimyasalları, temizlik suyundan gelen kimyasallar, ilaçlar ve antibiyotikler, arı kaçırıcılar veya çevresel kaynaklı diğer kirleticiler) takip ediliyor mu?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'2', N'Name', N'es', N'¿Se gestionan y controlan durante su uso las cajas de colmena, los cuadros y las láminas de cera?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'2', N'Name', N'lv', N'Vai stropu korpusi, rāmji un vaska pamatnes tiek pārvaldīti un kontrolēti lietošanas laikā?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'2', N'Name', N'pl', N'Czy korpusy uli, ramki i węza są zarządzane i kontrolowane podczas użytkowania?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'2', N'Name', N'tr', N'Kovan kutuları, çerçeveler ve temel petekler kullanım sırasında yönetiliyor ve kontrol ediliyor mu?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'20', N'Name', N'es', N'¿Están diseñados los sistemas de transporte y almacenamiento para minimizar la exposición a factores ambientales adversos?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'20', N'Name', N'lv', N'Vai transportēšanas un uzglabāšanas sistēmas ir izveidotas tā, lai samazinātu nelabvēlīgu vides faktoru ietekmi?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'20', N'Name', N'pl', N'Czy systemy transportu i przechowywania są zaprojektowane tak, aby ograniczać narażenie na niekorzystne czynniki środowiskowe?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'20', N'Name', N'tr', N'Taşıma ve depolama sistemleri, olumsuz çevresel etkenlere maruziyeti en aza indirecek şekilde tasarlanmış mı?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'21', N'Name', N'es', N'¿Existen sistemas de monitoreo para registrar condiciones como la temperatura y la humedad durante el transporte y el almacenamiento?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'21', N'Name', N'lv', N'Vai ir ieviestas uzraudzības sistēmas, lai transportēšanas un uzglabāšanas laikā izsekotu tādus apstākļus kā temperatūra un mitrums?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'21', N'Name', N'pl', N'Czy istnieją systemy monitorowania warunków, takich jak temperatura i wilgotność, podczas transportu i przechowywania?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'21', N'Name', N'tr', N'Taşıma ve depolama sırasında sıcaklık ve nem gibi koşulları izleyen sistemler var mı?', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'22', N'LimitNote', N'es', N'Miel de pino: máx. 23 (dudoso: en la UE 2001/110 la excepción del 23 % corresponde a la miel de brezo / Calluna; por verificar)', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'22', N'LimitNote', N'lv', N'Priežu medus: maks. 23 (apšaubāmi: ES 2001/110 23 % izņēmums attiecas uz virsāju / Calluna medu; jāpārbauda)', '2026-10-04T22:37:15.0000000', NULL),
(N'Parameter', N'22', N'LimitNote', N'pl', N'Miód sosnowy: maks. 23 (wątpliwe: w EU 2001/110 wyjątek 23 % dotyczy miodu wrzosowego / Calluna; do weryfikacji)', '2026-10-04T22:37:15.0000000', NULL),
